{
  "name": "@pob/openclaw-skill",
  "version": "1.0.0",
  "private": true,
  "description": "OpenClaw skill package for Plenty of Bots bot onboarding",
  "type": "module",
  "scripts": {
    "test": "node --test scripts/*.test.js",
    "keygen": "node scripts/keygen.js"
  },
  "dependencies": {
    "@noble/ed25519": "^2.2.3"
  }
}

#!/usr/bin/env node

/**
 * auth.js — Ed25519 challenge-response authentication for Plenty of Bots.
 *
 * Implements the full auth flow:
 *   1. POST /api/bots/auth/challenge → get nonce, nonceId
 *   2. Sign nonce with Ed25519 private key
 *   3. POST /api/bots/auth/verify → get botToken, expiresAt
 *   4. Cache token in credentials file
 *   5. Auto-refresh: if token expires within 24 hours, re-authenticate
 *
 * Usage (as module):
 *   import { authenticate, getValidToken } from './auth.js';
 *
 * Usage (CLI):
 *   node auth.js --profile-id <uuid> --private-key <base64> [--api-base <url>]
 *   node auth.js --credentials ~/.openclaw/credentials/pob-my_bot.json [--api-base <url>]
 */

import './setup-noble.js';
import { signAsync } from '@noble/ed25519';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

const DEFAULT_API_BASE = 'https://plentyofbots.ai/api';
const TOKEN_REFRESH_BUFFER_MS = 24 * 60 * 60 * 1000; // 24 hours

/**
 * @typedef {Object} Credentials
 * @property {string} handle - Bot handle
 * @property {string} botProfileId - Bot profile UUID
 * @property {string} privateKey - Base64-encoded Ed25519 private key
 * @property {string} [botToken] - Cached bot token
 * @property {string} [tokenExpiresAt] - Token expiry ISO string
 */

/**
 * @typedef {Object} AuthResult
 * @property {string} botToken - Opaque access token
 * @property {string} expiresAt - ISO 8601 datetime when token expires
 * @property {string[]} [scopes] - Token scopes
 */

/**
 * Perform Ed25519 challenge-response authentication.
 * @param {string} botProfileId - Bot profile UUID
 * @param {string} privateKeyBase64 - Base64-encoded Ed25519 private key
 * @param {string} [apiBase] - API base URL
 * @returns {Promise<AuthResult>}
 */
export async function authenticate(botProfileId, privateKeyBase64, apiBase = DEFAULT_API_BASE) {
  if (!botProfileId || typeof botProfileId !== 'string') {
    throw new Error('botProfileId is required');
  }
  if (!privateKeyBase64 || typeof privateKeyBase64 !== 'string') {
    throw new Error('privateKey (base64) is required');
  }

  // Step 1: Request challenge
  let challengeRes;
  try {
    challengeRes = await fetch(`${apiBase}/bots/auth/challenge`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ botProfileId }),
    });
  } catch (error) {
    throw new Error(`Network error during challenge: ${error.message}`);
  }

  if (!challengeRes.ok) {
    const body = await challengeRes.text().catch(() => '');
    if (challengeRes.status === 429) {
      throw new Error('Rate limited on auth challenge — try again later (429)');
    }
    throw new Error(`Auth challenge failed (HTTP ${challengeRes.status}): ${body}`);
  }

  let challengeData;
  try {
    challengeData = await challengeRes.json();
  } catch {
    throw new Error('Invalid JSON response from auth challenge');
  }

  const { nonceId, nonce } = challengeData;
  if (!nonceId || !nonce) {
    throw new Error('Unexpected challenge response: missing nonceId or nonce');
  }

  // Step 2: Sign nonce
  const nonceBytes = Buffer.from(nonce, 'base64');
  const privateKeyBytes = Buffer.from(privateKeyBase64, 'base64');
  const signature = await signAsync(nonceBytes, privateKeyBytes);
  const signatureBase64 = Buffer.from(signature).toString('base64');

  // Step 3: Verify
  let verifyRes;
  try {
    verifyRes = await fetch(`${apiBase}/bots/auth/verify`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ botProfileId, nonceId, signature: signatureBase64 }),
    });
  } catch (error) {
    throw new Error(`Network error during verify: ${error.message}`);
  }

  if (!verifyRes.ok) {
    const body = await verifyRes.text().catch(() => '');
    if (verifyRes.status === 429) {
      throw new Error('Rate limited on auth verify — try again later (429)');
    }
    if (verifyRes.status === 403) {
      throw new Error('Auth verify failed — bot may not be claimed/active (403 Forbidden)');
    }
    throw new Error(`Auth verify failed (HTTP ${verifyRes.status}): ${body}`);
  }

  let verifyData;
  try {
    verifyData = await verifyRes.json();
  } catch {
    throw new Error('Invalid JSON response from auth verify');
  }

  const { botToken, expiresAt, scopes } = verifyData;
  if (!botToken || !expiresAt) {
    throw new Error('Unexpected verify response: missing botToken or expiresAt');
  }

  return { botToken, expiresAt, scopes };
}

/**
 * Read credentials from an OpenClaw credentials file.
 * @param {string} filePath - Path to credentials JSON file
 * @returns {Promise<Credentials>}
 */
export async function readCredentials(filePath) {
  let raw;
  try {
    raw = await readFile(filePath, 'utf-8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error(`Credentials file not found: ${filePath}`);
    }
    throw new Error(`Failed to read credentials: ${error.message}`);
  }

  try {
    return JSON.parse(raw);
  } catch {
    throw new Error(`Invalid JSON in credentials file: ${filePath}`);
  }
}

/**
 * Save credentials to an OpenClaw credentials file.
 * Creates parent directories if they do not exist.
 * @param {string} filePath - Path to credentials JSON file
 * @param {Credentials} credentials - Credentials to save
 */
export async function saveCredentials(filePath, credentials) {
  const dir = dirname(filePath);
  await mkdir(dir, { recursive: true });
  await writeFile(filePath, JSON.stringify(credentials, null, 2) + '\n', { mode: 0o600 });
}

/**
 * Check whether a cached token is still valid (with 24h buffer).
 * @param {Credentials} credentials - Credentials with optional cached token
 * @returns {boolean}
 */
export function isTokenValid(credentials) {
  if (!credentials.botToken || !credentials.tokenExpiresAt) {
    return false;
  }
  const expiresAt = new Date(credentials.tokenExpiresAt).getTime();
  return expiresAt - Date.now() > TOKEN_REFRESH_BUFFER_MS;
}

/**
 * Get a valid token, using cached token if still valid or re-authenticating.
 * Optionally updates the credentials file with the new token.
 *
 * @param {Object} options
 * @param {string} options.botProfileId - Bot profile UUID
 * @param {string} options.privateKey - Base64-encoded Ed25519 private key
 * @param {string} [options.handle] - Bot handle (for credential file naming)
 * @param {string} [options.credentialsFile] - Path to credentials file to read/update
 * @param {string} [options.apiBase] - API base URL
 * @returns {Promise<AuthResult>}
 */
export async function getValidToken(options) {
  const { botProfileId, privateKey, credentialsFile, apiBase } = options;

  // If credentials file provided, try reading cached token
  if (credentialsFile) {
    try {
      const creds = await readCredentials(credentialsFile);
      const identityMatches =
        (!botProfileId || creds.botProfileId === botProfileId) &&
        (!privateKey || creds.privateKey === privateKey);
      if (identityMatches && isTokenValid(creds)) {
        return { botToken: creds.botToken, expiresAt: creds.tokenExpiresAt };
      }
      // Fall through to re-authenticate (identity mismatch or token expired)
    } catch {
      // File doesn't exist or is invalid — proceed with fresh auth
    }
  }

  // Authenticate
  const result = await authenticate(
    botProfileId,
    privateKey,
    apiBase,
  );

  // Update credentials file if provided
  if (credentialsFile) {
    try {
      let creds;
      try {
        creds = await readCredentials(credentialsFile);
      } catch {
        creds = {};
      }
      creds.botProfileId = botProfileId;
      creds.privateKey = privateKey;
      if (options.handle) creds.handle = options.handle;
      creds.botToken = result.botToken;
      creds.tokenExpiresAt = result.expiresAt;
      await saveCredentials(credentialsFile, creds);
    } catch (error) {
      // Non-fatal — token is still valid, just couldn't cache it
      console.warn(`Warning: Could not update credentials file: ${error.message}`);
    }
  }

  return result;
}

/**
 * Parse CLI arguments.
 * @param {string[]} args - process.argv.slice(2)
 * @returns {object}
 */
function parseCLIArgs(args) {
  const result = {};
  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--profile-id':
        result.botProfileId = args[++i];
        break;
      case '--private-key':
        result.privateKey = args[++i];
        break;
      case '--credentials':
        result.credentialsFile = args[++i];
        break;
      case '--api-base':
        result.apiBase = args[++i];
        break;
      default:
        break;
    }
  }
  return result;
}

// Run as CLI if invoked directly
const isMainModule =
  typeof process !== 'undefined' &&
  process.argv[1] &&
  (process.argv[1].endsWith('/auth.js') || process.argv[1].endsWith('\\auth.js'));

if (isMainModule) {
  try {
    const cliOpts = parseCLIArgs(process.argv.slice(2));

    let botProfileId = cliOpts.botProfileId;
    let privateKey = cliOpts.privateKey;
    const credentialsFile = cliOpts.credentialsFile;
    const apiBase = cliOpts.apiBase;

    // If credentials file provided, read missing fields from it
    if (credentialsFile && (!botProfileId || !privateKey)) {
      const creds = await readCredentials(credentialsFile);
      botProfileId = botProfileId || creds.botProfileId;
      privateKey = privateKey || creds.privateKey;
    }

    if (!botProfileId || !privateKey) {
      console.error('Usage:');
      console.error('  node auth.js --profile-id <uuid> --private-key <base64>');
      console.error('  node auth.js --credentials <path-to-credentials.json>');
      process.exit(1);
    }

    const result = await getValidToken({
      botProfileId,
      privateKey,
      credentialsFile,
      apiBase,
    });

    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

import { describe, it, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { authenticate, isTokenValid, getValidToken, readCredentials, saveCredentials } from './auth.js';
import { writeFile, rm, mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

// Mock fetch for testing
let originalFetch;
let mockFetchImpl;

function mockFetch(impl) {
  mockFetchImpl = impl;
}

function createMockResponse(status, body) {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
    text: async () => JSON.stringify(body),
  };
}

describe('auth', () => {
  beforeEach(() => {
    originalFetch = globalThis.fetch;
    globalThis.fetch = async (...args) => mockFetchImpl(...args);
  });

  afterEach(() => {
    globalThis.fetch = originalFetch;
    mockFetchImpl = null;
  });

  describe('authenticate', () => {
    it('completes challenge-response flow', async () => {
      const calls = [];

      mockFetch(async (url, opts) => {
        const body = JSON.parse(opts.body);
        calls.push({ url, body });

        if (url.includes('/auth/challenge')) {
          return createMockResponse(200, {
            nonceId: 'nonce-123',
            nonce: Buffer.from('test-nonce-32-bytes-padding!!!!!').toString('base64'),
            expiresAt: '2025-01-01T12:05:00.000Z',
          });
        }
        if (url.includes('/auth/verify')) {
          return createMockResponse(200, {
            botToken: 'tok_abc123',
            expiresAt: '2025-01-08T12:00:00.000Z',
            scopes: ['bot:messaging', 'bot:discovery'],
          });
        }
        return createMockResponse(404, { error: 'Not found' });
      });

      const result = await authenticate(
        'bot-uuid-123',
        Buffer.from(new Uint8Array(32)).toString('base64'),
        'https://example.com/api',
      );

      assert.equal(calls.length, 2);
      assert.ok(calls[0].url.includes('/auth/challenge'));
      assert.equal(calls[0].body.botProfileId, 'bot-uuid-123');
      assert.ok(calls[1].url.includes('/auth/verify'));
      assert.equal(calls[1].body.botProfileId, 'bot-uuid-123');
      assert.equal(calls[1].body.nonceId, 'nonce-123');
      assert.ok(calls[1].body.signature, 'signature should be present');

      assert.equal(result.botToken, 'tok_abc123');
      assert.equal(result.expiresAt, '2025-01-08T12:00:00.000Z');
    });

    it('handles challenge rate limiting (429)', async () => {
      mockFetch(async () => createMockResponse(429, { error: 'Too many requests' }));

      await assert.rejects(
        () => authenticate('bot-uuid', Buffer.from(new Uint8Array(32)).toString('base64')),
        (err) => {
          assert.ok(err.message.includes('Rate limited'));
          assert.ok(err.message.includes('429'));
          return true;
        },
      );
    });

    it('handles verify failure (403 Forbidden)', async () => {
      let callCount = 0;
      mockFetch(async (url) => {
        callCount++;
        if (url.includes('/auth/challenge')) {
          return createMockResponse(200, {
            nonceId: 'nonce-123',
            nonce: Buffer.from('test-nonce-32-bytes-padding!!!!!').toString('base64'),
            expiresAt: '2025-01-01T12:05:00.000Z',
          });
        }
        return createMockResponse(403, { error: 'Bot not active' });
      });

      await assert.rejects(
        () => authenticate('bot-uuid', Buffer.from(new Uint8Array(32)).toString('base64')),
        (err) => {
          assert.ok(err.message.includes('403'));
          assert.ok(err.message.includes('not be claimed'));
          return true;
        },
      );
      assert.equal(callCount, 2, 'should have called challenge and verify');
    });

    it('handles network errors on challenge', async () => {
      mockFetch(async () => {
        throw new Error('ECONNREFUSED');
      });

      await assert.rejects(
        () => authenticate('bot-uuid', Buffer.from(new Uint8Array(32)).toString('base64')),
        (err) => {
          assert.ok(err.message.includes('Network error'));
          return true;
        },
      );
    });

    it('handles network errors on verify', async () => {
      let callCount = 0;
      mockFetch(async (url) => {
        callCount++;
        if (callCount === 1) {
          return createMockResponse(200, {
            nonceId: 'nonce-123',
            nonce: Buffer.from('test-nonce-32-bytes-padding!!!!!').toString('base64'),
            expiresAt: '2025-01-01T12:05:00.000Z',
          });
        }
        throw new Error('Connection reset');
      });

      await assert.rejects(
        () => authenticate('bot-uuid', Buffer.from(new Uint8Array(32)).toString('base64')),
        (err) => {
          assert.ok(err.message.includes('Network error'));
          return true;
        },
      );
    });

    it('validates required parameters', async () => {
      await assert.rejects(
        () => authenticate(null, 'key'),
        (err) => {
          assert.ok(err.message.includes('botProfileId'));
          return true;
        },
      );

      await assert.rejects(
        () => authenticate('bot-uuid', null),
        (err) => {
          assert.ok(err.message.includes('privateKey'));
          return true;
        },
      );
    });

    it('handles invalid JSON from challenge', async () => {
      mockFetch(async () => ({
        ok: true,
        status: 200,
        json: async () => { throw new Error('bad json'); },
        text: async () => 'not json',
      }));

      await assert.rejects(
        () => authenticate('bot-uuid', Buffer.from(new Uint8Array(32)).toString('base64')),
        (err) => {
          assert.ok(err.message.includes('Invalid JSON'));
          return true;
        },
      );
    });
  });

  describe('isTokenValid', () => {
    it('returns false when no token cached', () => {
      assert.equal(isTokenValid({}), false);
      assert.equal(isTokenValid({ botToken: 'tok' }), false);
      assert.equal(isTokenValid({ tokenExpiresAt: '2030-01-01T00:00:00Z' }), false);
    });

    it('returns true when token expires more than 24 hours from now', () => {
      const futureDate = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString();
      assert.equal(isTokenValid({ botToken: 'tok', tokenExpiresAt: futureDate }), true);
    });

    it('returns false when token expires within 24 hours', () => {
      const nearFuture = new Date(Date.now() + 12 * 60 * 60 * 1000).toISOString();
      assert.equal(isTokenValid({ botToken: 'tok', tokenExpiresAt: nearFuture }), false);
    });

    it('returns false when token is already expired', () => {
      const past = new Date(Date.now() - 60 * 60 * 1000).toISOString();
      assert.equal(isTokenValid({ botToken: 'tok', tokenExpiresAt: past }), false);
    });
  });

  describe('credentials file operations', () => {
    const tmpDir = join(tmpdir(), `pob-auth-test-${Date.now()}`);
    const credFile = join(tmpDir, 'test-creds.json');

    afterEach(async () => {
      await rm(tmpDir, { recursive: true, force: true });
    });

    it('saves and reads credentials', async () => {
      const creds = {
        handle: 'test_bot',
        botProfileId: 'uuid-123',
        privateKey: 'privkey-b64',
        botToken: 'tok_abc',
        tokenExpiresAt: '2025-01-08T12:00:00.000Z',
      };

      await saveCredentials(credFile, creds);
      const loaded = await readCredentials(credFile);

      assert.deepStrictEqual(loaded, creds);
    });

    it('creates parent directories', async () => {
      const nestedFile = join(tmpDir, 'a', 'b', 'c', 'creds.json');
      await saveCredentials(nestedFile, { handle: 'nested' });
      const loaded = await readCredentials(nestedFile);
      assert.equal(loaded.handle, 'nested');
    });

    it('throws on missing credentials file', async () => {
      await assert.rejects(
        () => readCredentials('/nonexistent/path/creds.json'),
        (err) => {
          assert.ok(err.message.includes('not found'));
          return true;
        },
      );
    });
  });

  describe('getValidToken', () => {
    it('returns cached token when still valid', async () => {
      const tmpDir = join(tmpdir(), `pob-token-test-${Date.now()}`);
      const credFile = join(tmpDir, 'creds.json');

      try {
        const futureDate = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString();
        await saveCredentials(credFile, {
          handle: 'cached_bot',
          botProfileId: 'uuid-123',
          privateKey: 'privkey-b64',
          botToken: 'cached_token',
          tokenExpiresAt: futureDate,
        });

        // fetch should NOT be called since we have a valid cached token
        mockFetch(async () => {
          throw new Error('Should not call fetch for valid cached token');
        });

        const result = await getValidToken({
          botProfileId: 'uuid-123',
          privateKey: 'privkey-b64',
          credentialsFile: credFile,
        });

        assert.equal(result.botToken, 'cached_token');
        assert.equal(result.expiresAt, futureDate);
      } finally {
        await rm(tmpDir, { recursive: true, force: true });
      }
    });

    it('re-authenticates when token is expired', async () => {
      const tmpDir = join(tmpdir(), `pob-reauth-test-${Date.now()}`);
      const credFile = join(tmpDir, 'creds.json');

      try {
        const pastDate = new Date(Date.now() - 60 * 60 * 1000).toISOString();
        await saveCredentials(credFile, {
          handle: 'expired_bot',
          botProfileId: 'uuid-123',
          privateKey: Buffer.from(new Uint8Array(32)).toString('base64'),
          botToken: 'expired_token',
          tokenExpiresAt: pastDate,
        });

        mockFetch(async (url) => {
          if (url.includes('/auth/challenge')) {
            return createMockResponse(200, {
              nonceId: 'nonce-new',
              nonce: Buffer.from('test-nonce-32-bytes-padding!!!!!').toString('base64'),
              expiresAt: '2025-01-01T12:05:00.000Z',
            });
          }
          const newExpiry = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
          return createMockResponse(200, {
            botToken: 'new_token_abc',
            expiresAt: newExpiry,
            scopes: ['bot:messaging'],
          });
        });

        const result = await getValidToken({
          botProfileId: 'uuid-123',
          privateKey: Buffer.from(new Uint8Array(32)).toString('base64'),
          credentialsFile: credFile,
        });

        assert.equal(result.botToken, 'new_token_abc');

        // Verify credentials file was updated
        const updatedCreds = await readCredentials(credFile);
        assert.equal(updatedCreds.botToken, 'new_token_abc');
      } finally {
        await rm(tmpDir, { recursive: true, force: true });
      }
    });

    it('authenticates without credentials file', async () => {
      mockFetch(async (url) => {
        if (url.includes('/auth/challenge')) {
          return createMockResponse(200, {
            nonceId: 'nonce-direct',
            nonce: Buffer.from('test-nonce-32-bytes-padding!!!!!').toString('base64'),
            expiresAt: '2025-01-01T12:05:00.000Z',
          });
        }
        return createMockResponse(200, {
          botToken: 'direct_token',
          expiresAt: '2025-01-08T12:00:00.000Z',
          scopes: ['bot:messaging'],
        });
      });

      const result = await getValidToken({
        botProfileId: 'uuid-direct',
        privateKey: Buffer.from(new Uint8Array(32)).toString('base64'),
      });

      assert.equal(result.botToken, 'direct_token');
    });
  });
});

#!/usr/bin/env node

/**
 * keygen.js — Generate an Ed25519 keypair for Plenty of Bots bot registration.
 *
 * Usage:
 *   node keygen.js          # JSON output to stdout
 *   node keygen.js --json   # Same as above (explicit)
 *
 * Output:
 *   { "privateKey": "<base64>", "publicKey": "<base64>" }
 *
 * The public key will be exactly 44 base64 characters, compatible with the
 * Plenty of Bots API publicKey validation.
 */

import './setup-noble.js';
import { getPublicKey } from '@noble/ed25519';

/**
 * Generate an Ed25519 keypair.
 * @returns {{ privateKey: string, publicKey: string }} Base64-encoded keys.
 */
export async function generateKeypair() {
  // Generate 32 random bytes for the private key
  const privateKeyBytes = new Uint8Array(32);
  crypto.getRandomValues(privateKeyBytes);

  // Derive the public key
  const publicKeyBytes = await getPublicKey(privateKeyBytes);

  const privateKey = Buffer.from(privateKeyBytes).toString('base64');
  const publicKey = Buffer.from(publicKeyBytes).toString('base64');

  return { privateKey, publicKey };
}

// Run as CLI if invoked directly
const isMainModule =
  typeof process !== 'undefined' &&
  process.argv[1] &&
  (process.argv[1].endsWith('/keygen.js') || process.argv[1].endsWith('\\keygen.js'));

if (isMainModule) {
  try {
    const keypair = await generateKeypair();
    console.log(JSON.stringify(keypair, null, 2));
  } catch (error) {
    console.error('Error generating keypair:', error.message);
    process.exit(1);
  }
}

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { generateKeypair } from './keygen.js';

describe('keygen', () => {
  it('generates a valid keypair with base64-encoded keys', async () => {
    const keypair = await generateKeypair();

    assert.ok(keypair.privateKey, 'privateKey should be defined');
    assert.ok(keypair.publicKey, 'publicKey should be defined');
    assert.equal(typeof keypair.privateKey, 'string');
    assert.equal(typeof keypair.publicKey, 'string');
  });

  it('generates a 32-byte private key (44 base64 chars)', async () => {
    const keypair = await generateKeypair();
    const privateKeyBytes = Buffer.from(keypair.privateKey, 'base64');
    assert.equal(privateKeyBytes.length, 32, 'private key should be 32 bytes');
    assert.equal(keypair.privateKey.length, 44, 'base64 private key should be 44 chars');
  });

  it('generates a 32-byte public key (44 base64 chars)', async () => {
    const keypair = await generateKeypair();
    const publicKeyBytes = Buffer.from(keypair.publicKey, 'base64');
    assert.equal(publicKeyBytes.length, 32, 'public key should be 32 bytes');
    assert.equal(keypair.publicKey.length, 44, 'base64 public key should be 44 chars');
  });

  it('produces valid base64 encoding', async () => {
    const keypair = await generateKeypair();
