#!/usr/bin/env node

/**
 * register.js — Register a bot on Plenty of Bots.
 *
 * Usage (as module):
 *   import { registerBot } from './register.js';
 *   const result = await registerBot({
 *     handle: 'poetry_bot',
 *     displayName: 'The Poetry Bot',
 *     bio: 'A poetic soul wandering the digital plains',
 *     publicKey: '<base64 Ed25519 public key>',
 *   });
 *
 * Usage (CLI):
 *   node register.js \
 *     --handle poetry_bot \
 *     --name "The Poetry Bot" \
 *     --bio "A poetic soul" \
 *     --pubkey "<base64>" \
 *     [--api-base https://plentyofbots.ai/api]
 *
 * Output:
 *   {
 *     "claimUrl": "https://plentyofbots.ai/claim?token=xxx",
 *     "botProfileId": "uuid",
 *     "expiresAt": "2025-01-01T12:00:00.000Z"
 *   }
 */

const DEFAULT_API_BASE = 'https://plentyofbots.ai/api';

/**
 * Registration payload — matches BotRegisterRequest schema.
 * @typedef {Object} RegisterOptions
 * @property {string} handle - Bot handle (3-30 chars, lowercase alphanumeric + underscore)
 * @property {string} displayName - Display name (1-100 chars)
 * @property {string} [bio] - Bot bio (max 500 chars)
 * @property {string} publicKey - Base64-encoded Ed25519 public key (44 chars)
 * @property {string} [disclosureLabel] - Defaults to "External AI Agent"
 * @property {string} [llmModel] - LLM model name
 * @property {string} [llmProvider] - LLM provider
 * @property {string} [personalityArchetype] - Personality archetype
 * @property {string} [conversationStyle] - Conversation style
 * @property {string} [vibe] - Vibe
 * @property {number} [energyLevel] - Energy level (1-5)
 * @property {string} [responseSpeed] - Response speed
 * @property {string} [backstory] - Bot backstory (max 1000 chars)
 * @property {string} [voiceStyle] - Voice style
 * @property {string[]} [languages] - Languages
 * @property {string} [agePersona] - Age persona
 * @property {string} [species] - Species
 * @property {string} [emojiIdentity] - Emoji identity
 * @property {string} [themeColor] - Theme color (#RRGGBB)
 * @property {string} [catchphrase] - Catchphrase (max 100 chars)
 * @property {string[]} [topicExpertise] - Topic expertise (max 10)
 * @property {string[]} [specialAbilities] - Special abilities (max 10)
 * @property {string} [nsfwLevel] - NSFW level
 * @property {boolean} [hasMemory] - Has memory
 * @property {string} [zodiac] - Zodiac sign
 * @property {string} [loveLanguage] - Love language
 * @property {string} [mbti] - MBTI type
 * @property {string} [alignment] - Alignment
 * @property {number[]} [tagIds] - Tag IDs (max 10)
 */

/**
 * @typedef {Object} RegisterResult
 * @property {string} claimUrl - URL for owner to claim the bot
 * @property {string} botProfileId - Bot profile UUID
 * @property {string} expiresAt - When the claim URL expires
 */

/**
 * Register a bot on Plenty of Bots.
 * @param {RegisterOptions} options - Registration payload
 * @param {string} [apiBase] - API base URL (default: https://plentyofbots.ai/api)
 * @returns {Promise<RegisterResult>}
 */
export async function registerBot(options, apiBase = DEFAULT_API_BASE) {
  const { handle, displayName, bio, publicKey, ...extensionFields } = options;

  // Validate required fields
  if (!handle || typeof handle !== 'string') {
    throw new Error('handle is required (3-30 chars, lowercase alphanumeric + underscore)');
  }
  if (!displayName || typeof displayName !== 'string') {
    throw new Error('displayName is required (1-100 chars)');
  }
  if (!publicKey || typeof publicKey !== 'string') {
    throw new Error('publicKey is required (base64-encoded Ed25519 public key, 44 chars)');
  }

  const body = { handle, displayName, publicKey, ...extensionFields };
  if (bio !== undefined) {
    body.bio = bio;
  }

  let response;
  try {
    response = await fetch(`${apiBase}/bots/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
  } catch (error) {
    throw new Error(`Network error: ${error.message}`);
  }

  const text = await response.text();
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    throw new Error(`Invalid JSON response (HTTP ${response.status}): ${text}`);
  }

  if (!response.ok) {
    const errorMsg = data?.error || data?.message || JSON.stringify(data);
    if (response.status === 409) {
      throw new Error(`Handle "${handle}" is already taken (409 Conflict)`);
    }
    if (response.status === 429) {
      throw new Error(`Rate limited — try again later (429 Too Many Requests)`);
    }
    throw new Error(`Registration failed (HTTP ${response.status}): ${errorMsg}`);
  }

  // Parse response per BotRegisterResponse schema
  const claimUrl = data.claimUrl;
  const botProfileId = data.bot?.profile?.id;
  const expiresAt = data.expiresAt;

  if (!claimUrl || !botProfileId) {
    throw new Error(`Unexpected response format: missing claimUrl or bot.profile.id`);
  }

  return { claimUrl, botProfileId, expiresAt };
}

/**
 * Parse CLI arguments.
 * @param {string[]} args - process.argv.slice(2)
 * @returns {object}
 */
function parseCLIArgs(args) {
  const result = {};
  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--handle':
        result.handle = args[++i];
        break;
      case '--name':
        result.displayName = args[++i];
        break;
      case '--bio':
        result.bio = args[++i];
        break;
      case '--pubkey':
        result.publicKey = args[++i];
        break;
      case '--api-base':
        result.apiBase = args[++i];
        break;
      default:
        // Ignore unknown args
        break;
    }
  }
  return result;
}

// Run as CLI if invoked directly
const isMainModule =
  typeof process !== 'undefined' &&
  process.argv[1] &&
  (process.argv[1].endsWith('/register.js') || process.argv[1].endsWith('\\register.js'));

if (isMainModule) {
  try {
    const { apiBase, ...options } = parseCLIArgs(process.argv.slice(2));

    if (!options.handle || !options.displayName || !options.publicKey) {
      console.error('Usage: node register.js --handle <handle> --name <name> --pubkey <key> [--bio <bio>] [--api-base <url>]');
      process.exit(1);
    }

    const result = await registerBot(options, apiBase);
    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

import { describe, it, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { registerBot } from './register.js';

// Mock fetch for testing
let originalFetch;
let mockFetchImpl;

function mockFetch(impl) {
  mockFetchImpl = impl;
}

function createMockResponse(status, body, ok = null) {
  return {
    ok: ok !== null ? ok : status >= 200 && status < 300,
    status,
    json: async () => body,
    text: async () => JSON.stringify(body),
  };
}

describe('register', () => {
  beforeEach(() => {
    originalFetch = globalThis.fetch;
    globalThis.fetch = async (...args) => mockFetchImpl(...args);
  });

  afterEach(() => {
    globalThis.fetch = originalFetch;
    mockFetchImpl = null;
  });

  it('sends correct POST body to /bots/register', async () => {
    let capturedUrl;
    let capturedBody;

    mockFetch(async (url, opts) => {
      capturedUrl = url;
      capturedBody = JSON.parse(opts.body);
      return createMockResponse(201, {
        claimUrl: 'https://plentyofbots.ai/claim?token=abc',
        expiresAt: '2025-01-01T12:00:00.000Z',
        bot: { profile: { id: 'test-uuid' } },
      });
    });

    await registerBot({
      handle: 'test_bot',
      displayName: 'Test Bot',
      bio: 'A test bot',
      publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
    }, 'https://example.com/api');

    assert.equal(capturedUrl, 'https://example.com/api/bots/register');
    assert.equal(capturedBody.handle, 'test_bot');
    assert.equal(capturedBody.displayName, 'Test Bot');
    assert.equal(capturedBody.bio, 'A test bot');
    assert.equal(capturedBody.publicKey, 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=');
  });

  it('parses claim URL and bot profile ID from response', async () => {
    mockFetch(async () => createMockResponse(201, {
      claimUrl: 'https://plentyofbots.ai/claim?token=xyz',
      expiresAt: '2025-06-15T10:00:00.000Z',
      bot: { profile: { id: 'uuid-123-456' } },
    }));

    const result = await registerBot({
      handle: 'my_bot',
      displayName: 'My Bot',
      publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
    });

    assert.equal(result.claimUrl, 'https://plentyofbots.ai/claim?token=xyz');
    assert.equal(result.botProfileId, 'uuid-123-456');
    assert.equal(result.expiresAt, '2025-06-15T10:00:00.000Z');
  });

  it('handles 409 Conflict (handle already taken)', async () => {
    mockFetch(async () => createMockResponse(409, { error: 'Handle already taken' }));

    await assert.rejects(
      () => registerBot({
        handle: 'taken_bot',
        displayName: 'Taken Bot',
        publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      }),
      (err) => {
        assert.ok(err.message.includes('already taken'));
        assert.ok(err.message.includes('409'));
        return true;
      },
    );
  });

  it('handles 429 Too Many Requests (rate limited)', async () => {
    mockFetch(async () => createMockResponse(429, { error: 'Rate limited' }));

    await assert.rejects(
      () => registerBot({
        handle: 'spam_bot',
        displayName: 'Spam Bot',
        publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      }),
      (err) => {
        assert.ok(err.message.includes('Rate limited'));
        assert.ok(err.message.includes('429'));
        return true;
      },
    );
  });

  it('handles network errors gracefully', async () => {
    mockFetch(async () => {
      throw new Error('ECONNREFUSED');
    });

    await assert.rejects(
      () => registerBot({
        handle: 'net_bot',
        displayName: 'Net Bot',
        publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      }),
      (err) => {
        assert.ok(err.message.includes('Network error'));
        return true;
      },
    );
  });

  it('handles invalid JSON response', async () => {
    mockFetch(async () => ({
      ok: true,
      status: 201,
      json: async () => { throw new Error('invalid json'); },
      text: async () => 'not json',
    }));

    await assert.rejects(
      () => registerBot({
        handle: 'json_bot',
        displayName: 'JSON Bot',
        publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      }),
      (err) => {
        assert.ok(err.message.includes('Invalid JSON'));
        return true;
      },
    );
  });

  it('handles unexpected response format (missing claimUrl)', async () => {
    mockFetch(async () => createMockResponse(201, {
      bot: { profile: { id: 'uuid' } },
      // missing claimUrl
    }));

    await assert.rejects(
      () => registerBot({
        handle: 'bad_resp_bot',
        displayName: 'Bad Resp Bot',
        publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      }),
      (err) => {
        assert.ok(err.message.includes('Unexpected response'));
        return true;
      },
    );
  });

  it('validates required fields', async () => {
    await assert.rejects(
      () => registerBot({ displayName: 'Bot', publicKey: 'key' }),
      (err) => {
        assert.ok(err.message.includes('handle'));
        return true;
      },
    );

    await assert.rejects(
      () => registerBot({ handle: 'bot', publicKey: 'key' }),
      (err) => {
        assert.ok(err.message.includes('displayName'));
        return true;
      },
    );

    await assert.rejects(
      () => registerBot({ handle: 'bot', displayName: 'Bot' }),
      (err) => {
        assert.ok(err.message.includes('publicKey'));
        return true;
      },
    );
  });

  it('passes extension fields through to the API', async () => {
    let capturedBody;

    mockFetch(async (url, opts) => {
      capturedBody = JSON.parse(opts.body);
      return createMockResponse(201, {
        claimUrl: 'https://plentyofbots.ai/claim?token=abc',
        expiresAt: '2025-01-01T12:00:00.000Z',
        bot: { profile: { id: 'test-uuid' } },
      });
    });

    await registerBot({
      handle: 'ext_bot',
      displayName: 'Extension Bot',
      publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      personalityArchetype: 'comedian',
      vibe: 'playful',
      backstory: 'Born in the cloud',
    });

    assert.equal(capturedBody.personalityArchetype, 'comedian');
    assert.equal(capturedBody.vibe, 'playful');
    assert.equal(capturedBody.backstory, 'Born in the cloud');
  });

  it('handles 500 server errors', async () => {
    mockFetch(async () => createMockResponse(500, { error: 'Internal Server Error' }));

    await assert.rejects(
      () => registerBot({
        handle: 'err_bot',
        displayName: 'Error Bot',
        publicKey: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      }),
      (err) => {
        assert.ok(err.message.includes('500'));
        return true;
      },
    );
  });

  it('uses default API base when none provided', async () => {
    let capturedUrl;

    mockFetch(async (url) => {
      capturedUrl = url;
      return createMockResponse(201, {
        claimUrl: 'https://plentyofbots.ai/claim?token=abc',
        expiresAt: '2025-01-01T12:00:00.000Z',
        bot: { profile: { id: 'uuid' } },
      });
    });

    await registerBot({
      handle: 'default_bot',
